using Microsoft.AspNetCore.Mvc;
using RaceDay.Web.Infrastructure;
using RaceDay.Web.Models;

namespace RaceDay.Web.Controllers;
public class OrganiserController : Controller
{
    private readonly ApiClient _api;
    public OrganiserController(ApiClient api) => _api = api;
    private bool Allowed() => HttpContext.Session.GetString("UserRole") == "Organiser";
    public async Task<IActionResult> Index() { if (!Allowed()) return RedirectToAction("Login", "Account"); var r = await _api.GetAsync<List<EventVm>>("api/events/mine"); ViewBag.ApiError = r.Success ? null : r.Error; return View(r.Data ?? new()); }
    [HttpGet] public IActionResult CreateEvent() { if (!Allowed()) return RedirectToAction("Login", "Account"); return View("EventForm", new EventFormVm()); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateEvent(EventFormVm m) { if (!Allowed()) return RedirectToAction("Login", "Account"); if (!ModelState.IsValid) return View("EventForm", m); var r = await _api.PostAsync<EventVm>("api/events", new { m.EventName, m.EventDate, m.Location, m.Description, m.Distance, eventType = m.EventType }); if (!r.Success) { ModelState.AddModelError("", r.Error); return View("EventForm", m); } TempData["Success"] = "Event created."; return RedirectToAction(nameof(Index)); }
    [HttpGet] public async Task<IActionResult> EditEvent(int id) { if (!Allowed()) return RedirectToAction("Login", "Account"); var r = await _api.GetAsync<EventVm>($"api/events/{id}"); if (!r.Success || r.Data == null) { TempData["Error"] = r.Error; return RedirectToAction(nameof(Index)); } return View("EventForm", new EventFormVm { EventId=id, EventName=r.Data.EventName, EventDate=r.Data.EventDate, Location=r.Data.Location, Description=r.Data.Description, Distance=r.Data.Distance, EventType=r.Data.EventType }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> EditEvent(EventFormVm m) { if (!Allowed()) return RedirectToAction("Login", "Account"); if (!ModelState.IsValid) return View("EventForm", m); var r = await _api.PutAsync<EventVm>($"api/events/{m.EventId}", new { m.EventName, m.EventDate, m.Location, m.Description, m.Distance, eventType=m.EventType }); TempData[r.Success?"Success":"Error"] = r.Success ? "Event updated." : r.Error; return RedirectToAction(nameof(Index)); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteEvent(int id) { if (!Allowed()) return RedirectToAction("Login", "Account"); var r = await _api.DeleteAsync<System.Text.Json.JsonElement>($"api/events/{id}"); TempData[r.Success?"Success":"Error"] = r.Success ? "Event deleted." : r.Error; return RedirectToAction(nameof(Index)); }
    [HttpGet] public async Task<IActionResult> Categories(int eventId) { if (!Allowed()) return RedirectToAction("Login", "Account"); var ev = await _api.GetAsync<EventVm>($"api/events/{eventId}"); if (!ev.Success || ev.Data == null) { TempData["Error"] = ev.Error; return RedirectToAction(nameof(Index)); } var cats = await _api.GetAsync<List<CategoryVm>>($"api/events/{eventId}/categories"); ViewBag.Event = ev.Data; return View(cats.Data ?? new()); }
    [HttpGet] public IActionResult CreateCategory(int eventId) { if (!Allowed()) return RedirectToAction("Login", "Account"); return View("CategoryForm", new CategoryFormVm { EventId=eventId }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateCategory(CategoryFormVm m) { if (!Allowed()) return RedirectToAction("Login", "Account"); if (!ModelState.IsValid) return View("CategoryForm", m); var r=await _api.PostAsync<CategoryVm>($"api/events/{m.EventId}/categories", new {m.CategoryName,m.DistanceKm,m.MaxParticipants,m.EntryFee}); TempData[r.Success?"Success":"Error"] = r.Success?"Category created.":r.Error; return RedirectToAction(nameof(Categories),new{eventId=m.EventId}); }
    [HttpGet] public async Task<IActionResult> EditCategory(int id, int eventId) { if (!Allowed()) return RedirectToAction("Login", "Account"); var r = await _api.GetAsync<List<CategoryVm>>($"api/events/{eventId}/categories"); var c = r.Data?.FirstOrDefault(x => x.CategoryId == id); if (c == null) { TempData["Error"] = r.Error.Length > 0 ? r.Error : "Category not found."; return RedirectToAction(nameof(Categories), new { eventId }); } return View("CategoryForm", new CategoryFormVm { CategoryId = c.CategoryId, EventId = c.EventId, CategoryName = c.CategoryName, DistanceKm = c.DistanceKm, MaxParticipants = c.MaxParticipants, EntryFee = c.EntryFee }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> EditCategory(CategoryFormVm m) { if (!Allowed()) return RedirectToAction("Login", "Account"); if (!ModelState.IsValid) return View("CategoryForm", m); var r = await _api.PutAsync<CategoryVm>($"api/categories/{m.CategoryId}", new { m.CategoryName, m.DistanceKm, m.MaxParticipants, m.EntryFee }); TempData[r.Success ? "Success" : "Error"] = r.Success ? "Category updated." : r.Error; return RedirectToAction(nameof(Categories), new { eventId = m.EventId }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteCategory(int id, int eventId) { if (!Allowed()) return RedirectToAction("Login","Account"); var r=await _api.DeleteAsync<System.Text.Json.JsonElement>($"api/categories/{id}"); TempData[r.Success?"Success":"Error"] = r.Success?"Category deleted.":r.Error; return RedirectToAction(nameof(Categories),new{eventId}); }
    [HttpGet] public async Task<IActionResult> Enrolments(int eventId) { if (!Allowed()) return RedirectToAction("Login","Account"); var ev=await _api.GetAsync<EventVm>($"api/events/{eventId}"); var r=await _api.GetAsync<List<System.Text.Json.JsonElement>>($"api/events/{eventId}/enrolments"); ViewBag.Event=ev.Data; ViewBag.ApiError=r.Success?null:r.Error; return View(r.Data??new()); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> UpdateStatus(int id, int eventId, string status) { if (!Allowed()) return RedirectToAction("Login","Account"); var r=await _api.PutAsync<System.Text.Json.JsonElement>($"api/enrolments/{id}/status",new{status}); TempData[r.Success?"Success":"Error"]=r.Success?"Enrolment status updated.":r.Error; return RedirectToAction(nameof(Enrolments),new{eventId}); }
    [HttpGet] public async Task<IActionResult> Results(int eventId) { if (!Allowed()) return RedirectToAction("Login","Account"); var ev=await _api.GetAsync<EventVm>($"api/events/{eventId}"); var en=await _api.GetAsync<List<System.Text.Json.JsonElement>>($"api/events/{eventId}/enrolments"); var res=await _api.GetAsync<List<ResultVm>>($"api/results/event/{eventId}"); ViewBag.Event=ev.Data; ViewBag.Enrolments=en.Data??new(); ViewBag.ApiError=res.Success?null:res.Error; return View(res.Data??new()); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CaptureResult(ResultFormVm m, int eventId) { if (!Allowed()) return RedirectToAction("Login","Account"); if (!TimeSpan.TryParse(m.FinishTime,out var finish)) { TempData["Error"]="Enter finish time as hh:mm:ss."; return RedirectToAction(nameof(Results),new{eventId}); } var r=await _api.PostAsync<System.Text.Json.JsonElement>($"api/enrolments/{m.EnrolmentId}/results",new{finishTime=finish.ToString(),m.Position,m.Status}); TempData[r.Success?"Success":"Error"]=r.Success?"Race result recorded.":r.Error; return RedirectToAction(nameof(Results),new{eventId}); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> UploadImage(int eventId, IFormFile file) { if (!Allowed()) return RedirectToAction("Login","Account"); if(file==null||file.Length==0){TempData["Error"]="Select an image first.";return RedirectToAction(nameof(Index));} var r=await _api.UploadAsync<System.Text.Json.JsonElement>($"api/events/{eventId}/image",file); TempData[r.Success?"Success":"Error"]=r.Success?"Event image uploaded.":r.Error; return RedirectToAction(nameof(Index)); }
}
